-- Run with: supabase test db --local
-- RLS fixtures are created through the local Supabase Auth API first:
-- veriproof-test-a@example.test and veriproof-test-b@example.test.
begin;
select plan(47);

select ok((select count(*) = 14 from information_schema.tables where table_schema = 'public' and table_type = 'BASE TABLE' and table_name in ('projects','datasets','dataset_profiles','questions','claims','analysis_sessions','proof_obligations','evidence_items','analysis_runs','analysis_results','stability_tests','interpretation_tests','repair_plans','verdicts')), 'all 14 application tables exist');
select ok((select count(*) = 51 from (values ('projects','owner_id'),('projects','name'),('projects','status'),('datasets','project_id'),('datasets','storage_path'),('datasets','content_hash'),('datasets','file_size'),('dataset_profiles','dataset_id'),('dataset_profiles','profile'),('questions','project_id'),('questions','dataset_id'),('questions','question_text'),('claims','question_id'),('claims','claim_text'),('claims','status'),('claims','assumptions'),('analysis_sessions','claim_id'),('analysis_sessions','current_run_id'),('analysis_sessions','status'),('proof_obligations','analysis_session_id'),('proof_obligations','obligation_key'),('proof_obligations','status'),('proof_obligations','required'),('proof_obligations','metadata'),('evidence_items','analysis_session_id'),('evidence_items','obligation_id'),('evidence_items','value'),('analysis_runs','analysis_session_id'),('analysis_runs','parent_run_id'),('analysis_runs','run_number'),('analysis_runs','run_type'),('analysis_runs','execution_id'),('analysis_runs','code'),('analysis_runs','parameters'),('analysis_runs','status'),('analysis_results','analysis_run_id'),('analysis_results','result'),('stability_tests','analysis_run_id'),('stability_tests','sensitivity'),('interpretation_tests','analysis_run_id'),('interpretation_tests','invariant'),('repair_plans','analysis_session_id'),('repair_plans','failed_obligation_id'),('repair_plans','source_run_id'),('repair_plans','resulting_run_id'),('repair_plans','repair_steps'),('repair_plans','status'),('verdicts','analysis_session_id'),('verdicts','analysis_run_id'),('verdicts','verdict'),('verdicts','support_score')) as expected(table_name, column_name) join information_schema.columns c on c.table_schema = 'public' and c.table_name = expected.table_name and c.column_name = expected.column_name), 'required lifecycle and reproducibility columns exist');
select ok((select count(*) = 14 from pg_class c join pg_namespace n on n.oid = c.relnamespace where n.nspname = 'public' and c.relkind = 'r' and c.relrowsecurity), 'RLS enabled on all application tables');
select ok((select count(*) = 11 from pg_type t join pg_namespace n on n.oid = t.typnamespace where n.nspname = 'public' and t.typtype = 'e' and t.typname in ('project_status','dataset_status','claim_status','analysis_session_status','obligation_status','obligation_type','analysis_run_type','analysis_run_status','sensitivity_level','repair_plan_status','verdict_type')), 'all 11 expected enums exist');
select ok((select count(*) = 7 from pg_constraint where conname in ('evidence_items_obligation_id_analysis_session_id_fkey','repair_plans_failed_obligation_id_analysis_session_id_fkey','repair_plans_source_run_id_analysis_session_id_fkey','repair_plans_resulting_run_id_analysis_session_id_fkey','verdicts_analysis_run_id_analysis_session_id_fkey','analysis_sessions_current_run_same_session_fk','analysis_runs_parent_run_id_analysis_session_id_fkey') and contype = 'f'), 'all seven same-session composite foreign keys exist');
select ok(exists (select 1 from pg_constraint where conrelid = 'public.analysis_results'::regclass and contype = 'u' and conkey = array[(select attnum from pg_attribute where attrelid = 'public.analysis_results'::regclass and attname = 'analysis_run_id')]::smallint[]), 'one canonical result per run is enforced');
select ok(exists (select 1 from pg_constraint where conrelid = 'public.dataset_profiles'::regclass and contype = 'u' and conkey = array[(select attnum from pg_attribute where attrelid = 'public.dataset_profiles'::regclass and attname = 'dataset_id')]::smallint[]), 'one dataset profile per dataset is enforced');
select ok(exists (select 1 from pg_trigger where tgrelid = 'public.analysis_runs'::regclass and tgname = 'analysis_runs_lineage_guard' and not tgisinternal), 'run parent must be an earlier same-session run');
select ok(not exists (select 1 from pg_policies where schemaname = 'public' and tablename in ('analysis_runs','analysis_results','stability_tests','interpretation_tests','verdicts') and cmd = 'DELETE'), 'history tables have no DELETE policies');
select ok(not has_table_privilege('authenticated', 'public.verdicts', 'DELETE'), 'authenticated users cannot delete verdict history');
select ok(not has_column_privilege('authenticated', 'public.datasets', 'content_hash', 'UPDATE') and not has_column_privilege('authenticated', 'public.analysis_runs', 'code', 'UPDATE') and not has_table_privilege('authenticated', 'public.analysis_results', 'UPDATE') and not has_table_privilege('authenticated', 'public.verdicts', 'UPDATE'), 'dataset identity, run inputs, results, and verdict history cannot be overwritten');
select ok((select prosecdef and provolatile = 's' and proconfig @> array['search_path=""'] from pg_proc where oid = 'private.owns_project(uuid)'::regprocedure), 'ownership helper is SECURITY DEFINER, STABLE, with empty search_path');
select ok((select n.nspname = 'private' from pg_proc f join pg_namespace n on n.oid = f.pronamespace where f.oid = 'private.owns_project(uuid)'::regprocedure) and has_schema_privilege('authenticated', 'private', 'USAGE') and not has_schema_privilege('anon', 'private', 'USAGE'), 'helper is private and not exposed to anon');
select ok((select not public from storage.buckets where id = 'veriproof-datasets'), 'dataset storage bucket is private');
select ok((select count(*) = 3 from pg_policies where schemaname = 'storage' and tablename = 'objects' and policyname in ('veriproof_dataset_objects_select','veriproof_dataset_objects_insert','veriproof_dataset_objects_update')), 'private dataset storage policies exist');
select ok((select count(*) = 20 from pg_indexes where schemaname = 'public' and indexname in ('datasets_project_id_idx','questions_project_id_idx','questions_dataset_id_idx','claims_question_id_idx','analysis_sessions_claim_id_idx','analysis_sessions_current_run_id_idx','proof_obligations_analysis_session_id_idx','analysis_runs_analysis_session_id_idx','analysis_runs_parent_run_id_idx','analysis_runs_one_initial_per_session_idx','evidence_items_analysis_session_id_idx','evidence_items_obligation_id_idx','stability_tests_analysis_run_id_idx','interpretation_tests_analysis_run_id_idx','repair_plans_analysis_session_id_idx','repair_plans_failed_obligation_id_idx','repair_plans_source_run_id_idx','repair_plans_resulting_run_id_idx','verdicts_analysis_session_id_idx','verdicts_analysis_run_id_idx')), 'required FK and RLS path indexes exist');

-- Use real Auth-created users; do not insert rows into auth.users directly.
insert into public.projects (id, owner_id, name) select 'a0000000-0000-4000-8000-000000000001', id, 'RLS user A' from auth.users where email = 'veriproof-test-a@example.test';
insert into public.projects (id, owner_id, name) select 'b0000000-0000-4000-8000-000000000001', id, 'RLS user B' from auth.users where email = 'veriproof-test-b@example.test';
insert into public.datasets (id, project_id, name, original_filename, storage_path, content_hash, file_size) select 'a1000000-0000-4000-8000-000000000001', p.id, 'A dataset', 'a.csv', u.id::text || '/' || p.id::text || '/a1000000-0000-4000-8000-000000000001/a.csv', 'hash-a', 10 from public.projects p join auth.users u on u.id = p.owner_id where p.id = 'a0000000-0000-4000-8000-000000000001';
insert into public.datasets (id, project_id, name, original_filename, storage_path, content_hash, file_size) select 'b1000000-0000-4000-8000-000000000001', p.id, 'B dataset', 'b.csv', u.id::text || '/' || p.id::text || '/b1000000-0000-4000-8000-000000000001/b.csv', 'hash-b', 10 from public.projects p join auth.users u on u.id = p.owner_id where p.id = 'b0000000-0000-4000-8000-000000000001';
select set_config('veriproof.test.dataset_a_path', (select storage_path from public.datasets where id = 'a1000000-0000-4000-8000-000000000001'), true);
insert into public.dataset_profiles (dataset_id) values ('a1000000-0000-4000-8000-000000000001');
insert into public.questions (id, project_id, dataset_id, question_text) values ('a2000000-0000-4000-8000-000000000001','a0000000-0000-4000-8000-000000000001','a1000000-0000-4000-8000-000000000001','Question A'), ('b2000000-0000-4000-8000-000000000001','b0000000-0000-4000-8000-000000000001','b1000000-0000-4000-8000-000000000001','Question B');
insert into public.claims (id, question_id, claim_text) values ('a3000000-0000-4000-8000-000000000001','a2000000-0000-4000-8000-000000000001','Claim A'), ('b3000000-0000-4000-8000-000000000001','b2000000-0000-4000-8000-000000000001','Claim B');
insert into public.analysis_sessions (id, claim_id) values ('a4000000-0000-4000-8000-000000000001','a3000000-0000-4000-8000-000000000001'), ('b4000000-0000-4000-8000-000000000001','b3000000-0000-4000-8000-000000000001');
insert into public.proof_obligations (id, analysis_session_id, obligation_key, description) values ('a5000000-0000-4000-8000-000000000001','a4000000-0000-4000-8000-000000000001','a','Obligation A'), ('b5000000-0000-4000-8000-000000000001','b4000000-0000-4000-8000-000000000001','b','Obligation B');
insert into public.analysis_runs (id, analysis_session_id, run_number, run_type, execution_id, code) values ('a6000000-0000-4000-8000-000000000001','a4000000-0000-4000-8000-000000000001',1,'INITIAL','exec-a1','code-a'), ('b6000000-0000-4000-8000-000000000001','b4000000-0000-4000-8000-000000000001',1,'INITIAL','exec-b1','code-b');
insert into public.analysis_runs (id, analysis_session_id, parent_run_id, run_number, run_type, execution_id, code) values ('a6010000-0000-4000-8000-000000000001','a4000000-0000-4000-8000-000000000001','a6000000-0000-4000-8000-000000000001',2,'REPAIR','exec-a2','code-a2');
update public.analysis_sessions set current_run_id = 'a6000000-0000-4000-8000-000000000001' where id = 'a4000000-0000-4000-8000-000000000001';
update public.analysis_sessions set current_run_id = 'b6000000-0000-4000-8000-000000000001' where id = 'b4000000-0000-4000-8000-000000000001';
insert into public.evidence_items (analysis_session_id, obligation_id, evidence_type) values ('a4000000-0000-4000-8000-000000000001','a5000000-0000-4000-8000-000000000001','ROW');
insert into public.analysis_results (analysis_run_id, result) values ('a6000000-0000-4000-8000-000000000001','{}');
insert into public.stability_tests (analysis_run_id, perturbation_type, sensitivity) values ('a6000000-0000-4000-8000-000000000001','sample','STABLE');
insert into public.interpretation_tests (analysis_run_id, interpretation, invariant) values ('a6000000-0000-4000-8000-000000000001','interpretation A',true);
insert into public.repair_plans (analysis_session_id, failed_obligation_id, source_run_id, resulting_run_id, failure_reason) values ('a4000000-0000-4000-8000-000000000001','a5000000-0000-4000-8000-000000000001','a6000000-0000-4000-8000-000000000001','a6010000-0000-4000-8000-000000000001','test repair');
insert into public.verdicts (analysis_session_id, analysis_run_id, verdict) values ('a4000000-0000-4000-8000-000000000001','a6000000-0000-4000-8000-000000000001','INCONCLUSIVE');

select lives_ok($$insert into public.evidence_items (analysis_session_id, obligation_id, evidence_type) values ('a4000000-0000-4000-8000-000000000001','a5000000-0000-4000-8000-000000000001','ROW')$$, 'valid same-session evidence succeeds');
select throws_ok($$insert into public.evidence_items (analysis_session_id, obligation_id, evidence_type) values ('a4000000-0000-4000-8000-000000000001','b5000000-0000-4000-8000-000000000001','ROW')$$, '23503', null::text, 'cross-session evidence is rejected');
select throws_ok($$insert into public.repair_plans (analysis_session_id, failed_obligation_id, source_run_id, failure_reason) values ('a4000000-0000-4000-8000-000000000001','b5000000-0000-4000-8000-000000000001','a6000000-0000-4000-8000-000000000001','bad obligation')$$, '23503', null::text, 'cross-session repair obligation is rejected');
select throws_ok($$insert into public.repair_plans (analysis_session_id, failed_obligation_id, source_run_id, failure_reason) values ('a4000000-0000-4000-8000-000000000001','a5000000-0000-4000-8000-000000000001','b6000000-0000-4000-8000-000000000001','bad source')$$, '23503', null::text, 'cross-session repair source run is rejected');
select throws_ok($$insert into public.repair_plans (analysis_session_id, failed_obligation_id, source_run_id, resulting_run_id, failure_reason) values ('a4000000-0000-4000-8000-000000000001','a5000000-0000-4000-8000-000000000001','a6000000-0000-4000-8000-000000000001','b6000000-0000-4000-8000-000000000001','bad result')$$, '23503', null::text, 'cross-session repair resulting run is rejected');
select throws_ok($$insert into public.verdicts (analysis_session_id, analysis_run_id, verdict) values ('a4000000-0000-4000-8000-000000000001','b6000000-0000-4000-8000-000000000001','REFUTED')$$, '23503', null::text, 'cross-session verdict run is rejected');
set constraints analysis_sessions_current_run_same_session_fk immediate;
select throws_ok($$update public.analysis_sessions set current_run_id = 'b6000000-0000-4000-8000-000000000001' where id = 'a4000000-0000-4000-8000-000000000001'$$, '23503', null::text, 'cross-session current run is rejected');
set constraints analysis_sessions_current_run_same_session_fk deferred;
select throws_ok($$insert into public.analysis_runs (analysis_session_id, parent_run_id, run_number, run_type, execution_id, code) values ('a4000000-0000-4000-8000-000000000001','b6000000-0000-4000-8000-000000000001',3,'REPAIR','bad-parent','code')$$, '23514', null::text, 'cross-session parent run is rejected');
select lives_ok($$insert into public.analysis_runs (analysis_session_id, parent_run_id, run_number, run_type, execution_id, code) values ('a4000000-0000-4000-8000-000000000001','a6010000-0000-4000-8000-000000000001',3,'REVERIFICATION','exec-a3','code-a3')$$, 'same-session child run succeeds');
select throws_ok($$update public.analysis_runs set parent_run_id = id where id = 'a6010000-0000-4000-8000-000000000001'$$, '23514', null::text, 'run cannot be updated to reference itself as parent');
select ok(not exists (select 1 from public.analysis_runs where id = parent_run_id), 'no analysis run has itself as parent after rejected update');
select throws_ok($$insert into public.analysis_results (analysis_run_id, result) values ('a6000000-0000-4000-8000-000000000001','{}')$$, '23505', null::text, 'duplicate canonical result is rejected');
select throws_ok($$insert into public.dataset_profiles (dataset_id) values ('a1000000-0000-4000-8000-000000000001')$$, '23505', null::text, 'second dataset profile is rejected');

select set_config('request.jwt.claim.sub', (select id::text from auth.users where email = 'veriproof-test-a@example.test'), true);
set local role authenticated;
select lives_ok($$insert into public.projects (id, owner_id, name) values ('c0000000-0000-4000-8000-000000000001', (select auth.uid()), 'Created by user A')$$, 'authenticated user can create own project');
select is((select count(*)::int from public.projects where id = 'a0000000-0000-4000-8000-000000000001'), 1, 'user A reads own project');
select is((select count(*)::int from public.projects where id = 'b0000000-0000-4000-8000-000000000001'), 0, 'user A cannot read user B project');
select is((select count(*)::int from public.datasets where id = 'b1000000-0000-4000-8000-000000000001'), 0, 'user A cannot read user B dataset');
select lives_ok($$insert into storage.objects (bucket_id, name, owner, metadata) values ('veriproof-datasets', current_setting('veriproof.test.dataset_a_path'), auth.uid(), '{"size":10,"mimetype":"text/csv"}'::jsonb)$$, 'dataset owner can upload an object to the protected path');
select is((select count(*)::int from storage.objects where bucket_id = 'veriproof-datasets' and name = current_setting('veriproof.test.dataset_a_path')), 1, 'dataset owner can read their uploaded object');
select is((select count(*)::int from public.questions where id = 'b2000000-0000-4000-8000-000000000001'), 0, 'user A cannot read user B question');
select is((select count(*)::int from public.claims where id = 'b3000000-0000-4000-8000-000000000001'), 0, 'user A cannot read user B claim');
select is((select count(*)::int from public.analysis_sessions where id = 'b4000000-0000-4000-8000-000000000001'), 0, 'user A cannot read user B analysis');
select is((select count(*)::int from public.verdicts where analysis_session_id = 'b4000000-0000-4000-8000-000000000001'), 0, 'user A cannot read user B verdict');
select throws_ok($$delete from public.analysis_runs where id = 'a6000000-0000-4000-8000-000000000001'$$, '42501', null::text, 'authenticated cannot delete analysis runs');
select throws_ok($$delete from public.analysis_results where analysis_run_id = 'a6000000-0000-4000-8000-000000000001'$$, '42501', null::text, 'authenticated cannot delete analysis results');
select throws_ok($$delete from public.stability_tests where analysis_run_id = 'a6000000-0000-4000-8000-000000000001'$$, '42501', null::text, 'authenticated cannot delete stability tests');
select throws_ok($$delete from public.interpretation_tests where analysis_run_id = 'a6000000-0000-4000-8000-000000000001'$$, '42501', null::text, 'authenticated cannot delete interpretation tests');
select throws_ok($$delete from public.verdicts where analysis_session_id = 'a4000000-0000-4000-8000-000000000001'$$, '42501', null::text, 'authenticated cannot delete verdicts');
reset role;

select set_config('request.jwt.claim.sub', (select id::text from auth.users where email = 'veriproof-test-b@example.test'), true);
set local role authenticated;
select is((select count(*)::int from public.projects where id = 'b0000000-0000-4000-8000-000000000001'), 1, 'user B reads own project');
select is((select count(*)::int from storage.objects where bucket_id = 'veriproof-datasets' and name = current_setting('veriproof.test.dataset_a_path')), 0, 'another user cannot read the dataset owner object');
select throws_ok($$insert into storage.objects (bucket_id, name, owner, metadata) values ('veriproof-datasets', current_setting('veriproof.test.dataset_a_path'), auth.uid(), '{}'::jsonb)$$, '42501', null::text, 'another user cannot upload to the dataset owner path');
reset role;

select * from finish();
rollback;
